// ENG-2362 phase 1: does backend.q see template blocks written moments earlier?
let state = {};

export default {
  async run({ page }) {
    const result = await page.evaluate(async () => {
      const api = window.roamAlphaAPI;
      const title = `ENG-2362 repro ${Date.now()}`;
      const pageUid = api.util.generateUID();
      const h1Uid = api.util.generateUID();
      const childUid = api.util.generateUID();
      await api.data.page.create({ page: { title, uid: pageUid } });
      await api.data.block.create({
        location: { "parent-uid": pageUid, order: 0 },
        block: { string: "Heading", uid: h1Uid, heading: 1 },
      });
      await api.data.block.create({
        location: { "parent-uid": h1Uid, order: 0 },
        block: { string: "placeholder", uid: childUid },
      });
      // Same shape as the QB image query: block in page titled X whose parent is an H1.
      const q = `[:find ?uid :in $ ?title :where [?p :node/title ?title] [?b :block/page ?p] [?h :block/children ?b] [?h :block/heading 1] [?b :block/uid ?uid]]`;
      const backendImmediate = await api.data.backend.q(q, title);
      const localImmediate = await api.data.async.fast.q(q, title);
      let backendDelayMs = null;
      const start = Date.now();
      while (Date.now() - start < 15000) {
        const r = await api.data.backend.q(q, title);
        if (r.length) {
          backendDelayMs = Date.now() - start;
          break;
        }
        await new Promise((res) => setTimeout(res, 250));
      }
      return {
        pageUid,
        childUid,
        backendImmediate,
        localImmediate,
        backendDelayMs,
      };
    });
    state.pageUid = result.pageUid;
    return result;
  },
  async cleanup({ page }) {
    if (!state.pageUid) return;
    await page.evaluate(
      (uid) => window.roamAlphaAPI.data.page.delete({ page: { uid } }),
      state.pageUid,
    );
  },
};
