// ENG-2362: drive canvas image -> discourse node conversion and capture where the image lands.
const NODE_TYPE_TEXT = process.env.ENG2362_NODE_TYPE || "Issue";
const TS = Date.now();
const state = { canvasTitle: `Canvas/ENG-2362 repro ${TS}`, nodeContent: `eng2362 repro ${TS}` };
const logs = [];

const closeDialogs = async (page) => {
  for (let i = 0; i < 10; i++) {
    const open = await page.locator(".bp3-dialog, .bp3-overlay-open").count();
    if (!open) return;
    await page.keyboard.press("Escape");
    await page.waitForTimeout(300);
  }
};

export default {
  async run({ page }) {
    page.on("console", (m) => {
      const t = m.text();
      if (/Roam Query|:find|Inputs|🚨|error/i.test(t)) logs.push(t.slice(0, 3000));
    });
    await closeDialogs(page);
    const setup = await page.evaluate(async ({ canvasTitle }) => {
      const api = window.roamAlphaAPI;
      const img = api.data.fast.q(`[:find ?s :where [?b :block/string ?s] [(clojure.string/includes? ?s "firebasestorage")] [(clojure.string/includes? ?s ".png")] [(clojure.string/starts-with? ?s "![](")]]`).slice(0, 1)[0]?.[0];
      const src = img ? img.match(/\((https:[^)]+)\)/)[1] : null;
      const uid = api.util.generateUID();
      await api.data.page.create({ page: { title: canvasTitle, uid } });
      await api.ui.mainWindow.openPage({ page: { uid } });
      return { src, canvasUid: uid, smartblocks: !!window.roamjs?.extension?.smartblocks };
    }, state);
    state.canvasUid = setup.canvasUid;
    await page.waitForFunction((t) => !!window.tldrawApps?.[t], state.canvasTitle, { timeout: 30000 });
    await closeDialogs(page);
    await page.evaluate(({ t, src }) => {
      const editor = window.tldrawApps[t];
      const assetId = `asset:eng2362${Date.now()}`;
      editor.createAssets([{ id: assetId, type: "image", typeName: "asset", props: { name: "eng2362.png", src, w: 200, h: 150, mimeType: "image/png", isAnimated: false }, meta: {} }]);
      const shapeId = `shape:eng2362${Date.now()}`;
      editor.createShape({ id: shapeId, type: "image", x: 0, y: 0, props: { assetId, w: 200, h: 150 } });
      editor.select(shapeId);
      const b = editor.getShapePageBounds(shapeId);
      const vp = editor.getViewportScreenBounds();
      editor.setCamera({ x: -b.x - b.w / 2 + vp.w / 2, y: -b.y - b.h / 2 + vp.h / 2, z: 1 });
      window.__eng2362ShapeId = shapeId;
    }, { t: state.canvasTitle, src: setup.src });
    await page.waitForTimeout(800);
    const btn = page.locator('button[title="Convert to discourse node"]');
    await btn.waitFor({ timeout: 10000 });
    await btn.click();
    const dialog = page.locator(".roamjs-canvas-dialog");
    await dialog.waitFor({ timeout: 15000 });
    await dialog.locator("button.bp3-button").filter({ hasNotText: /Confirm|Cancel/ }).first().click();
    await page.locator(".bp3-menu-item", { hasText: new RegExp(`^${NODE_TYPE_TEXT}$`) }).first().click();
    await dialog.locator("input, textarea").first().fill(state.nodeContent);
    await page.waitForTimeout(300);
    await dialog.locator("button", { hasText: "Confirm" }).click();
    await page.waitForTimeout(10000);

    const result = await page.evaluate(async ({ t, nodeTypeText }) => {
      const api = window.roamAlphaAPI;
      const editor = window.tldrawApps[t];
      const shapes = editor.getCurrentPageShapes().map((s) => ({ type: s.type, props: { uid: s.props.uid, title: s.props.title, imageUrl: s.props.imageUrl, nodeTypeId: s.props.nodeTypeId } }));
      const dn = shapes.find((s) => s.type !== "image");
      const nodeType = window.roamjs.extension.queryBuilder.getDiscourseNodes().find((n) => n.text === nodeTypeText);
      const out = { shapes, canvasSettings: nodeType?.canvasSettings };
      if (!dn) return out;
      const title = dn.props.title;
      out.pageTree = api.pull("[:node/title :block/uid {:block/children [:block/string :block/uid :block/order :block/heading {:block/children ...}]}]", [":block/uid", dn.props.uid]);
      const decomposed = {
        titleOnly: `[:find ?uid :in $ ?t :where [?p :node/title ?t] [?p :block/uid ?uid]]`,
        blocksInPage: `[:find ?s ?h :in $ ?t :where [?p :node/title ?t] [?b :block/page ?p] [?b :block/string ?s] [(get-else $ ?b :block/heading 0) ?h]]`,
        withParent: `[:find ?uid :in $ ?t :where [?p :node/title ?t] [?b :block/page ?p] [?h1 :block/children ?b] [?b :block/uid ?uid]]`,
        full: `[:find ?uid :in $ ?t :where [?p :node/title ?t] [?b :block/page ?p] [?h1 :block/children ?b] [?h1 :block/heading 1] [?b :block/uid ?uid]]`,
      };
      out.manual = {};
      for (const [k, q] of Object.entries(decomposed)) {
        out.manual[k] = { backend: await api.data.backend.q(q, title), local: await api.data.async.fast.q(q, title) };
      }
      return out;
    }, { t: state.canvasTitle, nodeTypeText: NODE_TYPE_TEXT });
    state.nodePageUid = result.pageTree?.[":block/uid"];
    return { setup, nodeContent: state.nodeContent, ...result, logs };
  },
  async cleanup({ page }) {
    await page.evaluate(async (s) => {
      const api = window.roamAlphaAPI;
      if (s.nodePageUid) await api.data.page.delete({ page: { uid: s.nodePageUid } });
      if (s.canvasUid) await api.data.page.delete({ page: { uid: s.canvasUid } });
    }, state);
    return state;
  },
};
